export function decisionsView(ctx){
 const items=ctx.decisions||[];
 const columns=['Proposed','Assigned','In progress','Waiting for input','Completed'];
 const today=new Date().toISOString().slice(0,10);
 const plusDays=n=>{const d=new Date(today+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
 const active=items.filter(x=>!['Completed','Closed'].includes(x.status)).length;
 const high=items.filter(x=>!['Completed','Closed'].includes(x.status)&&x.priority==='High').length;
 const done=items.filter(x=>['Completed','Closed'].includes(x.status)).length;
 const waiting=items.filter(x=>x.status==='Waiting for input').length;
 const dueSoon=items.filter(x=>!['Completed','Closed'].includes(x.status)&&x.due>=today&&x.due<=plusDays(3)).length;
 const cortexLed=items.filter(x=>/Cortex|AI Analyst/i.test(x.source||'')).length;
 const nextStatus=status=>status==='Proposed'?'Assigned':status==='Assigned'?'In progress':status==='In progress'?'Waiting for input':status==='Waiting for input'?'Completed':'';
 const notifyLabel=x=>x.notification?.state==='sent'?'Email sent':x.notification?.state==='failed'?'Email failed':x.notification?.state==='pending_configuration'?'Email pending':'Not notified';
 const card=x=>`<article class="decision-card"><div class="decision-card-top"><span class="decision-id">${e(x.id)}</span><span class="decision-priority ${String(x.priority).toLowerCase()}">${e(x.priority)}</span></div><h4>${e(x.title)}</h4><p class="decision-card-problem">${e(x.problem)}</p><div class="decision-meta"><span>Owner<strong>${e(x.owner)}</strong><small>${e(x.ownerEmail||'')}</small></span><span>Due<strong>${e(x.due)}</strong></span><span>Context<strong>${e(x.scenario||'India trade risk · 2026 baseline')}</strong></span><span>Source<strong>${e(x.source||'Manual decision')}</strong></span></div>${x.expectedImpact?`<p class="decision-impact"><strong>Expected outcome</strong><span>${e(x.expectedImpact)}</span></p>`:''}<div class="decision-card-actions"><button class="text-button" data-decision-view="${e(x.id)}">View evidence</button>${x.ownerEmail?`<button class="text-button" data-decision-notify="${e(x.id)}">Notify owner</button>`:''}${nextStatus(x.status)?`<button class="secondary small" data-decision-status="${e(x.id)}" data-next-status="${e(nextStatus(x.status))}">${e(nextStatus(x.status))} →</button>`:''}<button class="text-button danger" data-decision-delete="${e(x.id)}">Remove</button></div></article>`;
 const col=status=>{const rows=items.filter(x=>x.status===status);return `<section class="decision-column"><div class="decision-column-head"><h3>${e(status)}</h3><span>${rows.length}</span></div>${rows.length?rows.map(card).join(''):'<div class="decision-empty">No decisions here.</div>'}</section>`;};
 const closed=items.filter(x=>x.status==='Closed');
 return `${heading('DECISION WORKSPACE','Decision board','Convert governed trade-risk insight into an owned mitigation action and track it through execution.',action('Create decision','new-decision','plus',true))}
 <div class="decision-workflow-note">${icon('check')}<div><strong>Detect → Understand → Simulate → Decide → Track</strong><br><span>Every decision keeps its evidence, source, owner, due date, status and expected outcome together.</span></div></div>
 <div class="decision-summary">
  <article><span>Active decisions</span><strong>${active}</strong><small>Still requiring execution</small></article>
  <article><span>High priority</span><strong>${high}</strong><small>Trade-risk actions requiring attention</small></article>
  <article><span>Due in 3 days</span><strong>${dueSoon}</strong><small>Near-term mitigation window</small></article>
  <article><span>Cortex-led decisions</span><strong>${cortexLed}</strong><small>${done} completed · ${waiting} waiting</small></article>
 </div>
 <section class="panel"><div class="panel-heading"><div><h2>Mitigation pipeline</h2><p>Move each action from proposed mitigation to completion while retaining the analytical evidence that triggered it.</p></div><span class="subtle-label">${items.length} decisions</span></div>
 ${items.length?`<div class="decision-board">${columns.map(col).join('')}</div>${closed.length?`<div class="closed-decisions"><strong>Closed</strong><span>${closed.length} archived decision${closed.length===1?'':'s'}</span></div>`:''}`:`<div class="decision-board-empty"><div class="decision-board-empty-icon">${icon('check')}</div><h3>No mitigation decisions yet</h3><p>Create one manually or generate a recommendation from AI Analyst to start the execution workflow.</p><button class="primary" data-action="new-decision">${icon('plus')}Create first decision</button></div>`}
 </section>
 <section class="panel"><div class="panel-heading"><div><h2>Decision quality checklist</h2><p>Use this during the hackathon demo to show the difference between an answer and an operational decision.</p></div></div><div class="decision-checklist-grid"><article><span class="eyebrow">EVIDENCE</span><h3>Evidence</h3><p>Country, commodity, transport dependency or weather signal is traceable to the governed Snowflake model.</p></article><article><span class="eyebrow">ACTION</span><h3>Action</h3><p>The decision records what will be evaluated or changed, not just what the analysis discovered.</p></article><article><span class="eyebrow">OWNERSHIP</span><h3>Ownership</h3><p>A named role and due date make the mitigation executable.</p></article><article><span class="eyebrow">OUTCOME</span><h3>Outcome</h3><p>Expected impact and lifecycle status make follow-through visible.</p></article></div></section>`;
}

