export function profileView(){
 const session=typeof window!=='undefined'?(window.__ONTOTRAIL_SESSION||{}):{};
 const role=session.role==='client_admin'?'Client Admin':session.role==='platform_admin'?'OntoTrail Platform Admin':'Client User';
 const email=session.email||'';
 const tenant=session.tenant||'Nova Mobility India';
 const savedName=(()=>{try{return typeof localStorage!=='undefined'?(localStorage.getItem('ontotrail_profile_name')||session.name||''):(session.name||'');}catch{return session.name||'';}})();
 return `${heading('ACCOUNT','Profile','Your workspace identity and access details.')}<section class="panel profile-page"><div class="profile-summary"><div class="profile-avatar-large">${e((savedName||'User').split(/\\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase())}</div><div><h2>${e(savedName||'Workspace user')}</h2><p>${e(role)} · ${e(tenant)}</p></div></div><form id="profile-form" class="profile-form"><label class="field-label">Name<input class="text-input" name="name" required maxlength="80" value="${e(savedName)}"></label><label class="field-label">Email<input class="text-input" value="${e(email)}" readonly></label><label class="field-label">Role<input class="text-input" value="${e(role)}" readonly></label><label class="field-label">Organization<input class="text-input" value="${e(tenant)}" readonly></label><div class="profile-actions"><button class="primary" type="submit">Save name</button><button class="secondary" type="button" data-profile-password>Change password</button><button class="text-button danger" type="button" data-auth-logout>Log out</button></div><p class="helper">Password credentials are managed by the workspace administrator in this hackathon environment.</p></form></section>`;
}

export function aboutView(ctx){
 const t=ctx.tradeData||{},s=t.summary||{};
 const pct=v=>new Intl.NumberFormat('en-IN',{maximumFractionDigits:1}).format(Number(v||0))+'%';
 return `${heading('WORKSPACE GUIDE','Nova Mobility India trade-risk workspace','A fictional enterprise client context powered by real Snowflake Marketplace trade and weather intelligence, Cortex Analyst and an execution-oriented Decision Board.')}
 <div class="guide-grid"><section class="panel guide"><h2>Start here</h2><ol><li>Ask a governed question in AI Analyst.</li><li>Use Control tower to identify Nova Mobility supply-chain risks requiring attention.</li><li>Open Nova operations for internal records, or Marketplace intel / Trade network for external context.</li><li>Use Scenario lab for structural stress tests.</li><li>Convert an AI insight into an owned Decision Board action.</li></ol><button class="primary" data-action="go-analyst">Open AI Analyst ${icon('arrow')}</button></section>
 <section class="panel guide"><h2>Connection status</h2><dl class="preview-list"><div><dt>Workspace</dt><dd>Nova Mobility India</dd></div><div><dt>Trade source</dt><dd>Oxford Economics TradePrism</dd></div><div><dt>Weather source</dt><dd>Pelmorex Weather Source: Frostbyte</dd></div><div><dt>Semantic layer</dt><dd>ONTOTRAIL_TRADE_RISK_ANALYST</dd></div><div><dt>Weather coverage</dt><dd>${pct(s.weatherCoveragePct)}</dd></div></dl><p>Snowflake credentials remain server-side. Client analytics require an authenticated workspace session.</p></section></div>
 <section class="panel guide"><h2>Client simulation boundary</h2><p><strong>Nova Mobility India is a fictional enterprise used for the hackathon demonstration.</strong> TradePrism and Pelmorex remain external Marketplace intelligence; they are not claimed as Nova Mobility proprietary transaction, supplier, PO or shipment data.</p></section><section class="panel guide"><h2>How the model works</h2><div class="guide-columns"><div><h3>Structural exposure</h3><p>TradePrism provides annual bilateral trade flows and forecasts by origin, destination, HS4 hierarchy and transport-mode measures.</p><h3>External signal</h3><p>Pelmorex forecast locations are aggregated to country-level weather indicators before being joined to origin-country trade exposure.</p></div><div><h3>Risk interpretation</h3><p>Weather risk is an OntoTrail-derived heuristic. Countries without Pelmorex coverage remain visible with weather coverage explicitly unavailable.</p><h3>Scope</h3><p>The model does not claim individual suppliers, purchase orders, exact shipment routes, ports or delivery ETAs from Marketplace trade-flow data.</p></div></div></section>
 <section class="panel guide"><h2>Decision workflow</h2><p>AI insight → governed evidence → owner → due date → status → outcome. Decision data is currently stored in the authenticated prototype workspace, while email delivery remains a placeholder.</p></section>`;
}
export function orderDetail(o,d){return `<div class="dialog-head"><div><span class="eyebrow">ORDER TRACE</span><h2 id="detail-title">${o.id}</h2><p>${e(o.customer)} · ${e(o.partName)}</p></div><button class="icon-button" data-close="detail-dialog" aria-label="Close order details">${icon('close')}</button></div><div class="detail-body">${status(o)}<div class="detail-metrics"><div><span>Full order value</span><strong>${money(o.orderValuePaise)}</strong></div><div><span>Units short by deadline</span><strong>${o.shortfall} / ${o.quantity}</strong></div></div><dl class="preview-list"><div><dt>Customer due date</dt><dd>${date(o.due)}</dd></div><div><dt>Parts required by</dt><dd>${date(o.requiredBy)}</dd></div><div><dt>Expected completion</dt><dd>${date(o.expectedDate)}${o.lateDays?` · ${o.lateDays}d late`:''}</dd></div><div><dt>Unallocated units</dt><dd>${o.unallocated}</dd></div></dl><h3>Allocation trail</h3>${o.allocations.length?`<div class="allocation-list">${o.allocations.map(a=>`<article><span class="allocation-dot ${a.onTime?'':'late'}"></span><div><button class="order-link" data-source="${a.sourceId}">${a.sourceId}</button><p>${a.quantity} units available ${date(a.eta)}</p><span class="status ${a.onTime?'covered':'risk'}">${a.onTime?'Before required date':'Arrives after requirement'}</span></div></article>`).join('')}</div>`:'<p>No source can cover this order.</p>'}<h3>Supporting evidence</h3>${evidenceButtons(o.evidence)}<p class="helper">Dates are model outputs from the active scenario. Source documents retain their original snapshot values.</p></div>`;}
export const viewMap={analyst:analystView,overview,operations:operationsView,orders:ordersView,scenarios:scenariosView,network:networkView,evidence:evidenceView,decisions:decisionsView,governance:governanceView,profile:profileView,about:aboutView};
